import {hintPending} from './practice.js?v=20261015-review1';
import {modelPrompt} from './model-prompts.js?v=20261015-review1';
import {escape} from './documents.js?v=20261015-review1';
import {answered,isCorrect} from './answers.js?v=20261015-review1';
export function questionHtml(s,index){
 const q=s.exam.questions[index],value=s.answers[index],show=s.graded&&!s.rehearsal,correct=isCorrect(q,value);
 return `<section id="question-${index}" class="examQuestion" data-question-section="${index}"><div class="questionMeta"><span>${index+1}. 객관식${q.dimension?' · '+escape(q.dimension):''}</span><button class="outline ${s.flags[index]?'active':''}" data-flag="${index}" aria-pressed="${s.flags[index]}" ${s.graded?'disabled':''}>다시 풀 문제 ⚑</button><button class="outline" data-intro>지문으로 이동 ↑</button>${s.exam.documents.length||show?'<button class="outline assistLauncher" data-open-assistant>AI 어시스트</button>':''}${show?`<span class="status ${correct?'':'wrong'}">${correct?'○ 정답':answered(value)?'× 오답':'미응답'}</span>`:''}</div>${q.scenario?`<blockquote class="scenario">${escape(q.scenario)}</blockquote>`:''}<p class="questionText">${escape(q.prompt)}</p><p class="selectLabel">답안을 선택하세요 ↴</p><div class="options" role="radiogroup" aria-label="${index+1}번 답안">${q.options.map((o,i)=>`<button role="radio" aria-checked="${value===i}" data-answer="${i}" data-answer-question="${index}" ${s.graded?'disabled':''} class="option ${value===i?'selected':''} ${show&&i===q.answer?'correctAnswer':''}"><span class="circle">${i+1}</span><span>${escape(o)}</span></button>`).join('')}</div>${show?`<div class="explanation"><strong>정답 ${q.answer+1} · ${escape(q.topic)}</strong><p>${escape(q.explanation)}</p><div class="modelPrompt"><div class="modelPromptHead"><strong>정답 도출 모범 프롬프트</strong><div class="modelPromptActions"><button class="primary" data-retry-prompt="${index}" ${hintPending(s)?'disabled':''}>모범 프롬프트로 재실행</button><button class="outline" data-copy-prompt="${index}">복사</button></div></div><p>재실행하면 ${index+1}번 문제·필요한 자료·모범 프롬프트를 자동으로 불러와 AI에 전송합니다. 답안과 점수는 유지됩니다.</p><pre data-model-prompt-text tabindex="0" aria-label="${index+1}번 모범 프롬프트">${escape(modelPrompt(s.exam,index))}</pre><small id="promptCopyStatus-${index}" role="status"></small></div>${q.evidence?.length?`<p><strong>판단 근거</strong></p><ul>${q.evidence.map(e=>`<li>${escape(e.document)} · ${escape(e.locator)}</li>`).join('')}</ul>`:''}<p><strong>보기별 해설</strong></p><ol>${q.options.map((o,i)=>`<li><strong>${escape(o)}</strong><p>${escape(q.optionReasons?.[i]||q.explanation)}</p></li>`).join('')}</ol></div>`:''}<hr class="divider"></section>`;
}
